do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 The New Heaven and the New Earth$j$, $j${"readings": [{"title": "Revelation 21 (King James Version)", "url": "/portal/bible/Revelation/21"}, {"title": "Revelation 22 (King James Version)", "url": "/portal/bible/Revelation/22"}], "body": "Read Revelation 21 and Revelation 22 in the King James Version. Then read this lesson.\n\nThe Bible ends with a promise of hope. In Revelation 21 John saw a new heaven and a new earth, and the holy city, new Jerusalem, coming down from God out of heaven. God will dwell with His people, and He will wipe away all tears from their eyes. There will be no more death, sorrow, crying or pain, because the former things are passed away. The One on the throne said, Behold, I make all things new. In chapter 22 John saw the river of the water of life and the tree of life, and Jesus said, I am Alpha and Omega, the beginning and the end. The book closes with an invitation: whosoever will, let him take the water of life freely. The last prayer is, Even so, come, Lord Jesus. The final words are, The grace of our Lord Jesus Christ be with you all. Amen.\n\nKey words: new heaven, tears, make all things new, water of life, invitation.\n\nYour task: (1) Tell what Revelation 21:4 promises. (2) Write Revelation 21:5 in your own words. (3) Explain the invitation in Revelation 22:17.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "This is the last lesson of our New Testament survey, and it is about the last two chapters of the Bible. After all of the struggle and judgment in Revelation, the story ends with joy. God's plan from the beginning was to live with His people, and the last chapters show that plan complete.\n\nRevelation 21:1 says, And I saw a new heaven and a new earth: for the first heaven and the first earth were passed away; and there was no more sea. Verse 2 says, And I John saw the holy city, new Jerusalem, coming down from God out of heaven, prepared as a bride adorned for her husband. Then comes the great promise in verse 3. And I heard a great voice out of heaven saying, Behold, the tabernacle of God is with men, and he will dwell with them, and they shall be his people, and God himself shall be with them, and be their God. In the Garden of Eden, God walked with Adam and Eve. In the new creation, God lives with His people forever.\n\nRevelation 21:4 may be the most comforting verse in the Bible for people who are hurting. And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. If you have lost a loved one, if you are sick or if you are afraid, this promise is for you. Then the One on the throne spoke. Revelation 21:5 says, And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful. God does not just fix the old world. He makes all things new.\n\nVerse 6 says, And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely. And verse 7 says, He that overcometh shall inherit all things; and I will be his God, and he shall be my son.\n\nIn chapter 22 John saw the river and the tree of life, as in the Garden of Eden. Revelation 22:1 says, And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb. Verse 2 says, In the midst of the street of it, and on either side of the river, was there the tree of life, which bare twelve manner of fruits, and yielded her fruit every month: and the leaves of the tree were for the healing of the nations. Verse 13 repeats the words of Jesus. I am Alpha and Omega, the beginning and the end, the first and the last.\n\nThe Bible ends with an invitation to everyone. Revelation 22:17 says, And the Spirit and the bride say, Come. And let him that heareth say, Come. And let him that is athirst come. And whosoever will, let him take the water of life freely. The offer is free, and it is for whosoever will. The last prayer of the Bible is found in verse 20. He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus. And the Bible closes with a blessing in verse 21. The grace of our Lord Jesus Christ be with you all. Amen.\n\nYour task is to tell what Revelation 21:4 promises, write Revelation 21:5 in your own words, and explain the invitation in Revelation 22:17. Then take the four question check and the Unit 6 quiz. After that, you are ready for the final assessment and the final exam.\n\nYou have studied the whole New Testament, from the birth of Jesus to the new heaven and new earth. Excellence, Faith, Purpose. May the grace of our Lord Jesus Christ be with you."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 The New Heaven and the New Earth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Hope in the Book of Revelation$j$, $j${"prompt": "Choose one passage from this unit: Revelation 1:18, Revelation 3:20, Revelation 5:12, Revelation 12:11, Revelation 19:16, Revelation 21:4 or Revelation 22:17. Write one paragraph of 150 to 200 words. Quote the passage from the King James Version with the reference, explain what it meant to the first readers who were suffering, and tell how it gives hope to a student today.", "rubric": "Total 100. Accurate quotation of the passage with the reference: 20. Explains the meaning for the first readers: 30. Shows how the passage gives hope today: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Hope in the Book of Revelation$j$);
end
$seed$;
